import type { Readable } from 'node:stream';

/** An opened object: its bytes as a stream, and its size in bytes. */
export interface StoredObject {
  readonly body: Readable;
  readonly size: number;
}

/** The key names no object. */
export class ObjectNotFoundError extends Error {
  constructor(key: string) {
    super(`No stored object under ${key}`);
    this.name = 'ObjectNotFoundError';
  }
}

/**
 * Private object storage for document files (ADR-003). Keys are generated by
 * the application (see storage-key.ts), never taken from user input.
 * Implementations: FilesystemStorage (development, tests) and S3Storage (R2).
 */
export abstract class ObjectStorage {
  /** Stores `body` under `key`, replacing any existing object. */
  abstract put(key: string, body: Buffer, contentType: string): Promise<void>;

  /**
   * Opens the object for reading. Resolves only once the object is known to
   * exist, so callers can still answer with an error before streaming.
   * Throws ObjectNotFoundError for a missing key. The caller must consume or
   * destroy the stream.
   */
  abstract get(key: string): Promise<StoredObject>;

  /** Removes the object. Removing a missing object succeeds, so retries are safe. */
  abstract delete(key: string): Promise<void>;
}
